<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\TenantConfigWelcomeEmailVO;

trait TenantConfigWelcomeEmailAccessor
{
    private ?TenantConfigWelcomeEmailVO $_welcomeEmail = null;
    public function getWelcomeEmail(): ?string
    {
        return $this->_welcomeEmail?->value();
    }
    public function welcomeEmail(): ?TenantConfigWelcomeEmailVO
    {
        return $this->_welcomeEmail;
    }
    public function isWelcomeEmailChanged(?self $original = null): bool
    {
        return null !== $this->_welcomeEmail && !$this->_welcomeEmail->equals($original?->_welcomeEmail);
    }
    public function withWelcomeEmail(TenantConfigWelcomeEmailVO|string|null $welcomeEmail): self
    {
        $copy = clone $this;
        $copy->_welcomeEmail = TenantConfigWelcomeEmailVO::from($welcomeEmail);
        return $copy;
    }
}
